head.script:
                function correctNumber( isString, value )
                {
                    if( isString )
                    {
                        return value;
                    }
                    else
                    {
                        // avoid sending of empty string
                        if( "" == value )
                        {
                            return null;
                        }

                        // replace decimal comma with decimal dot 
                        value = "" + value; 
                        var commaRE = /,/;
                        return value.replace( commaRE, ".");
                    }
                }

                function setValue( isString, address, value )
                {
                    try
                    {
                        value = correctNumber( isString, value ); // null is returned if correction fails
                        if( value == null )
                        {
                            return;
                        }
                    
                        var xmlhttp;
                        if (window.XMLHttpRequest)
                        {
                            // code for IE7+, Firefox, Chrome, Opera, Safari
                            xmlhttp = new XMLHttpRequest();
                        }
                        else
                        {
                            // code for IE6, IE5
                            xmlhttp = new ActiveXObject( "Microsoft.XMLHTTP" );
                        }
                        xmlhttp.open( "GET", location.pathname + "?set(" + address + "," + value + ")", true );
                        xmlhttp.send( null );
                    }
                    catch(error)
                    {
                        // intentionaly do nothing
                    }
                }
